MARKS = ['А 5 Вл', 'А 5 Нл', 'А 8 Вл', 'А 8 Вн', 'А 8 Вт', 'А 11 Вл', 'А 11 Вн',
         'А 11 Нл', 'А 11 Нн', 'А 16 Вл', 'А 16 Вн', 'А 16 Нн', 'А 22 Нн', 'А 22 Нт',
         'А 22 От', 'А 22 Он', 'А 22 Вн', 'А 22 Вт']
LAYER = {'В': 'верхний слой', 'Н': 'нижний слой', 'О': 'основание'}
TRAFFIC = {'л': 'лёгкие', 'н': 'нормальные', 'т': 'тяжёлые'}
