def gost_marks(apps, schema_editor):
    AsphaltMix = apps.get_model('catalog', 'AsphaltMix')
    AsphaltMix.objects.filter(title__in=OLD).delete()
    for i, mark in enumerate(MARKS, 1):
        code = mark.split()[-1]
        AsphaltMix.objects.update_or_create(title=mark, defaults={
            'mix_type': LAYER[code[0]], 'grade': TRAFFIC[code[1]], 'purpose': '',
            'price_label': 'По запросу', 'price_prefix': '', 'order': i * 10})
    for model, field, old, new in TEXTS:
        Model = apps.get_model('core', model)
        for obj in Model.objects.filter(**{f'{field}__contains': old}):
            setattr(obj, field, getattr(obj, field).replace(old, new))
            obj.save(update_fields=[field])



